def is_prime_sum_pair(n: int) -> tuple[int, int] | None:
    """Return a pair of primes summing to the even integer n, or None."""
    if n < 4 or n % 2 != 0:
        return None

    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    for a in range(2, n // 2 + 1):
        b = n - a
        if is_prime(a) and is_prime(b):
            return (a, b)
    return None
